from collections import defaultdict

tree=defaultdict(list)

message=_("Code").first()["json"].get("Message", "")
product=_("If1").first()["json"].get("Message", "")

for item in items:

    row=item.get("json", {})

    name=str(row.get("Name", "")).strip()
    tags=str(row.get("Tags", "")).strip().lower()
    price=row.get("Price", "")

    if not name or not tags:
        continue

    tag_list=[
        t.strip()
        for t in tags.split(",")
        if t.strip()
    ]

    for tag in tag_list:
        tree[tag].append({
            "name": name,
            "price": price
        })

return [{
    "json":{
        "tree":dict(tree),
        "message":message,
        "product":product
    }
}]

